using System;
using System.IO;
using System.Collections;
using DG.Tweening;
using UnityEngine;
namespace CloudCafe.Crafting {
 public sealed partial class FrontGrindController:MonoBehaviour {
  public readonly GrindModel Model=new GrindModel();
  public readonly PuckPrepModel Prep=new PuckPrepModel();
  Transform prepTool;int prepKind;bool prepHeld,prepContact,rotating,pressing;float priorAngle,pressY;Vector3 prepOffset;
  FrontGrindArt art;Sequence motion;AudioSource motor,contact;Font font;Rect frame;bool held,paused,smoke;Vector3 pointerOffset;string message="손잡이를 잡아 들어 올려 보세요.";string review;
  bool Moving=>(motion!=null&&motion.IsActive())||(cameraMotion!=null&&cameraMotion.IsActive());
  void Awake(){Application.targetFrameRate=60;Application.runInBackground=true;art=new FrontGrindArt();CreateHandCursor();font=Font.CreateDynamicFontFromOSFont("Malgun Gothic",16);motor=gameObject.AddComponent<AudioSource>();contact=gameObject.AddComponent<AudioSource>();motor.clip=Sound(true);motor.loop=true;motor.volume=0;motor.Play();contact.clip=Sound(false);contact.volume=.28f;latteSmoke=Array.IndexOf(Environment.GetCommandLineArgs(),"-latteSmoke")>=0;smoke=latteSmoke||Array.IndexOf(Environment.GetCommandLineArgs(),"-frontSmoke")>=0;review=Path.GetFullPath(Path.Combine(Application.dataPath,"../../Review"));if(latteSmoke)review=Path.Combine(review,"Practice");if(smoke){Directory.CreateDirectory(review);Application.logMessageReceived+=Failure;}InitializeCoffeeBeans();}
  AudioClip Sound(bool loop){int count=loop?22050:3308;var values=new float[count];var random=new System.Random(43);float low=0;for(int i=0;i<count;i++){low=Mathf.Lerp(low,(float)random.NextDouble()*2-1,.32f);values[i]=loop?(low*.21f+Mathf.Sin(i*.071f)*.035f):(low*.8f+Mathf.Sin(i*.3f)*.25f)*Mathf.Exp(-i/380f);}var clip=AudioClip.Create(loop?"temporary motor":"temporary tool contact",count,1,22050,false);clip.SetData(values,0);return clip;}
  void Layout(){float s=Mathf.Min(Screen.width/960f,Screen.height/540f);frame=new Rect((Screen.width-960*s)/2,(Screen.height-540*s)/2,960*s,540*s);}
  Ray MouseRay(){return art.Camera.ViewportPointToRay(new Vector3((Input.mousePosition.x-frame.x)/frame.width,(Input.mousePosition.y-frame.y)/frame.height,0));}
  Vector3 ReachPoint(){float enter;var ray=MouseRay();return new Plane(Vector3.up,new Vector3(0,.72f,0)).Raycast(ray,out enter)?ray.GetPoint(enter):art.Tool.position;}
  public bool Grab(){if(paused||Moving||held||prepKind!=0||cupHeld||Brew.Inserted)return false;bool fromDock=Model.Slot==CraftSlot.Grinder;if(!Model.PickUp()){message="분쇄를 멈췄어요. 마지막 가루가 떨어진 뒤 잡아 주세요.";return false;}held=true;art.Hand.gameObject.SetActive(true);pointerOffset=art.Tool.position-ReachPoint();pointerOffset.y=0;motion=DOTween.Sequence();if(fromDock)motion.Append(art.Tool.DOMoveZ(-.24f,.2f).SetEase(Ease.InOutSine));motion.Append(art.Tool.DOMoveY(.72f,.28f).SetEase(Ease.OutSine));motion.Join(art.Tool.DOLocalRotate(new Vector3(-3,0,0),.2f)).OnComplete(()=>{pointerOffset=art.Tool.position-ReachPoint();pointerOffset.y=0;motion=null;});message=Prep.Complete?"머신의 둥근 헤드 아래로 가져가 끼워 주세요.":"들었어요. 바스켓을 그라인더 출구 아래로 가져가세요.";return true;}
  public void Reach(Vector3 point){if(!held||Moving)return;art.Tool.position=new Vector3(Mathf.Clamp(point.x,-1.8f,4.3f),.72f,Mathf.Clamp(point.z,-1.15f,.22f));}
  public void Drop(){if(!held||Moving)return;blockedDockMessage=NearMachine()&&!Prep.Complete?PrepRequired():null;if(InsertAtMachine())return;held=false;var p=art.Tool.position;bool dock=Vector2.Distance(new Vector2(p.x,p.z),new Vector2(art.Dock.x,art.Dock.z))<.43f;bool mat=Vector2.Distance(new Vector2(p.x,p.z),new Vector2(art.Mat.x,art.Mat.z))<.6f;Model.Drop(dock?CraftSlot.Grinder:mat?CraftSlot.Mat:CraftSlot.Invalid);Seat(Model.Slot);}
  void Seat(CraftSlot slot){bool dock=slot==CraftSlot.Grinder;Vector3 target=dock?art.Dock:art.Mat;motion=DOTween.Sequence();
   if(dock){motion.Append(art.Tool.DOMove(new Vector3(target.x,.72f,-.16f),.23f).SetEase(Ease.InOutSine));motion.Append(art.Tool.DOMove(target,.22f).SetEase(Ease.OutSine));}else motion.Append(art.Tool.DOMove(new Vector3(target.x,.44f,target.z),.3f).SetEase(Ease.InOutSine)).Append(art.Tool.DOMove(target,.25f).SetEase(Ease.InSine));
   motion.Join(art.Tool.DORotate(Vector3.zero,.2f));motion.AppendCallback(()=>{contact.Play();art.Hand.gameObject.SetActive(false);message=dock?"받침에 닿았어요. 기계 앞의 금색 버튼을 누르세요.":Prep.Complete?"포터필터를 들어 오른쪽 머신의 둥근 헤드 아래로 가져가세요.":Model.Complete?"오른쪽의 낮고 둥근 도구를 잡아 바스켓 위에 얹으세요.":"작업대에 내려놓았어요.";if(blockedDockMessage!=null){message=blockedDockMessage;blockedDockMessage=null;}});motion.OnComplete(()=>motion=null);
  }
  public void Switch(){if(paused||Moving||held)return;if(Model.Toggle())message=Model.Running?"가루가 내려옵니다. 같은 버튼으로 멈출 수 있어요.":"마지막 가루가 떨어지고 있어요.";else message="빈 바스켓을 먼저 분쇄 받침에 놓아 주세요.";}
  public void ResetStation(){Kill();EndLatteView();blockedDockMessage=null;ResetBrew();Model.Reset();Prep.Reset();held=paused=prepHeld=prepContact=rotating=pressing=false;prepKind=0;prepTool=null;art.Tool.position=art.Mat;art.Tool.rotation=Quaternion.identity;art.Distributor.position=art.DistributorHome;art.Distributor.rotation=Quaternion.identity;art.Tamper.position=art.TamperHome;art.PrepHand.gameObject.SetActive(false);art.Hand.gameObject.SetActive(false);message="손잡이를 잡아 들어 올려 보세요.";}
  public bool PickPrep(int kind){if(paused||Moving||held||prepKind!=0||!Model.Complete||Prep.Complete)return false;if(kind==2&&!Prep.Leveled){message="먼저 낮고 둥근 도구로 표면을 고르게 돌려 주세요.";return false;}prepKind=kind;prepTool=kind==1?art.Distributor:art.Tamper;prepHeld=true;art.PrepHand.gameObject.SetActive(true);motion=DOTween.Sequence().Append(prepTool.DOMoveY(.72f,.25f)).OnComplete(()=>{prepOffset=prepTool.position-ReachPoint();prepOffset.y=0;motion=null;});message="바스켓 가운데로 가져가 놓으세요.";return true;}
  public void ReachPrep(Vector3 point){if(!prepHeld||Moving)return;prepTool.position=new Vector3(Mathf.Clamp(point.x,-1.8f,4.3f),.72f,Mathf.Clamp(point.z,-1.15f,.25f));}
  bool NearPrepBasket(){if(prepTool==null)return false;var p=prepTool.position;var b=art.Tool.position;var pv=art.Camera.WorldToViewportPoint(p);var bv=art.Camera.WorldToViewportPoint(b+Vector3.up*.15f);return PrepPlacementModel.Near(p.x-b.x,p.z-b.z,pv.x-bv.x,pv.y-bv.y);}
  public void DropPrep(){if(!prepHeld||Moving)return;prepHeld=false;var p=prepTool.position;var b=art.Tool.position;if(!NearPrepBasket()){ReturnPrep();return;}prepContact=true;Vector3 target=b+Vector3.up*(prepKind==1?.13f:.11f);motion=DOTween.Sequence().Append(prepTool.DOMove(target,.25f).SetEase(Ease.InOutSine)).AppendCallback(()=>{contact.Play();message=prepKind==1?"둥근 도구를 누른 채 원을 그리며 돌려 주세요.":"탬퍼 머리를 잡고 아래로 당겨 꾹 누른 뒤 놓으세요.";}).OnComplete(()=>motion=null);}
  public void RotatePrep(float delta){if(prepKind!=1||!prepContact||Moving)return;rotating=true;Prep.BeginLevel();Prep.Rotate(delta);prepTool.Rotate(0,delta,0,Space.World);}
  public void EndRotate(){rotating=false;Prep.EndLevel();if(Prep.Leveled){message="표면이 고르게 됐어요. 이제 손잡이가 높은 탬퍼를 잡으세요.";ReturnPrep();}}
  public void PressPrep(float depth,float dt){if(prepKind!=2||!prepContact||Moving)return;pressing=true;Prep.Press(depth,dt);prepTool.position=art.Tool.position+Vector3.up*(.11f-.035f*Prep.Depth);}
  public void EndPress(){pressing=false;Prep.Release();if(Prep.Complete){contact.Play();message="표면 정리와 탬핑 완료. 이제 머신에 장착할 준비가 됐어요.";ReturnPrep();}else if(prepTool!=null){prepTool.position=art.Tool.position+Vector3.up*.11f;message="조금 더 깊게 눌러 잠깐 다진 뒤 놓아 주세요.";}}
  void ReturnPrep(){prepContact=prepHeld=false;Vector3 home=prepKind==1?art.DistributorHome:art.TamperHome;motion=DOTween.Sequence().Append(prepTool.DOMoveY(.65f,.18f)).Append(prepTool.DOMove(new Vector3(home.x,.65f,home.z),.22f)).Append(prepTool.DOMove(home,.2f)).AppendCallback(()=>{contact.Play();art.PrepHand.gameObject.SetActive(false);prepKind=0;prepTool=null;if(Prep.Complete)EnterBrewView();}).OnComplete(()=>motion=null);}
  float MouseAngle(){Vector3 v=art.Camera.WorldToViewportPoint(art.Tool.position);Vector2 d=new Vector2(Input.mousePosition.x-frame.x-v.x*frame.width,Input.mousePosition.y-frame.y-v.y*frame.height);return Mathf.Atan2(d.y,d.x)*Mathf.Rad2Deg;}
  void Kill(){if(motion!=null&&motion.IsActive()){motion.Pause();motion.Kill();}motion=null;}
  void Update(){Layout();if(HandleCoffeeBeanInput())return;if(!smoke&&!latteActive&&Application.isFocused&&!paused&&Input.GetMouseButtonDown(0)){Cursor.lockState=CursorLockMode.Confined;}if(latteActive){UpdateLatte();return;}if(!smoke){if(Input.GetKeyDown(KeyCode.R))ResetStation();if(Input.GetKeyDown(KeyCode.Escape))TogglePause();if(!paused){
    if(Input.GetMouseButtonDown(0)&&!held&&!prepHeld&&!cupHeld&&!Moving){RaycastHit hit;if(Physics.Raycast(MouseRay(),out hit,20)){
     if(prepContact&&prepTool!=null&&hit.transform.IsChildOf(prepTool)){if(prepKind==1){rotating=true;priorAngle=MouseAngle();}else if(Prep.BeginTamp()){pressing=true;pressY=Input.mousePosition.y;}}
     else if(TryBrewClick(hit.transform)){}else if(hit.transform==art.Switch)Switch();else if(hit.transform.IsChildOf(art.Distributor))PickPrep(1);else if(hit.transform.IsChildOf(art.Tamper))PickPrep(2);else if(hit.transform.IsChildOf(art.Tool))Grab();}}
    if(held){if(!Moving)DragHeld(MouseViewport());if(!Input.GetMouseButton(0)&&!Moving)Drop();}
    if(prepHeld){if(!Moving)ReachPrep(ReachPoint()+prepOffset);if(!Input.GetMouseButton(0)&&!Moving)DropPrep();}
    if(rotating){float angle=MouseAngle();RotatePrep(Mathf.DeltaAngle(priorAngle,angle));priorAngle=angle;if(Input.GetMouseButtonUp(0))EndRotate();}
    if(pressing){PressPrep(Mathf.Clamp01((pressY-Input.mousePosition.y)/(frame.height*.085f)),Time.deltaTime);if(Input.GetMouseButtonUp(0))EndPress();}
    if(Input.GetKeyDown(KeyCode.Space)){if(brewView)SwitchBrew();else Switch();}}}
   if(!paused)Model.Step(Time.deltaTime);art.SetPrepHint(prepHeld,prepHeld&&NearPrepBasket());if(prepHeld&&!Moving&&NearPrepBasket())message="이 근처에서 놓으면 바스켓 가운데에 맞춰집니다.";UpdateBrew();art.Update(Model,Prep,Time.time);if(prepTool!=null){art.PrepHand.position=prepTool.position;art.PrepHand.rotation=prepKind==1?prepTool.rotation:Quaternion.identity;}motor.volume=Mathf.MoveTowards(motor.volume,(Model.Running||Brew.Running)&&!paused?.3f:0,Time.deltaTime);if(Model.Ready&&Model.Slot==CraftSlot.Grinder&&!Moving)message="18g이 담겼어요. 손잡이를 잡아 꺼내고 오른쪽 매트에 내려놓으세요.";
  }
  void OnApplicationFocus(bool focused){if(!focused&&!smoke){ReleaseLattePointer();if(latteActive&&!paused)TogglePause();Cursor.visible=true;Model.Running=false;StopBrewForFocus();if(held){Kill();held=false;Model.Drop(CraftSlot.Invalid);Seat(Model.Slot);}}}
  void OnDisable(){if(!smoke)ReleaseLattePointer();}
  void OnGUI(){Layout();if(DrawCoffeeBeanBrowser())return;if(latteActive){DrawLatteGUI();return;}GUI.DrawTexture(frame,art.Pixels,ScaleMode.StretchToFill,false);var old=GUI.matrix;GUI.matrix=Matrix4x4.TRS(new Vector3(frame.x,frame.y),Quaternion.identity,Vector3.one*frame.width/960);var label=new GUIStyle(GUI.skin.label){font=font,fontSize=18,normal={textColor=new Color(1,.92f,.78f)}};var bg=GUI.color;GUI.color=new Color(.07f,.09f,.14f,.95f);GUI.DrawTexture(new Rect(0,0,960,42),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(0,477,960,63),Texture2D.whiteTexture);GUI.color=bg;GUI.Label(new Rect(18,9,550,30),"직접 커피 만들기 · 분쇄부터 추출까지",label);GUI.Label(new Rect(685,9,270,30),brewView?"추출 "+Brew.InCup.ToString("0.0")+" / 36g":"바스켓 "+Model.Grounds.ToString("0.0")+" / 18g",label);GUI.Label(new Rect(18,482,925,30),paused?"잠시 쉬는 중 · Esc로 계속":message,label);label.fontSize=13;GUI.Label(new Rect(18,514,925,23),brewView?"머신 밑에 끼우기 → 손잡이를 오른쪽으로 돌리기 → 컵 놓기 → 금색 버튼  |  R 다시 · Esc 쉬기":"손잡이 드래그 → 왼쪽 출구 밑 받침 → 금색 버튼 → 오른쪽 매트 → 표면 정리 → 탬핑  |  R 다시 · Esc 쉬기",label);GUI.matrix=old;DrawCoffeeBeanBadge();}
  IEnumerator Start(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-coffeeBeanSmoke")>=0)yield return CoffeeBeanSmoke();else if(latteSmoke){SeedLattePractice();yield return LatteSmoke();File.WriteAllText(Path.Combine(review,"result.json"),"{\"passed\":true,\"mode\":\"latte practice\",\"spaceRelease\":true,\"whitePattern\":true}");Debug.Log("LATTE_PRACTICE_PASSED");Application.Quit(0);}else if(smoke)yield return Smoke();else if(Array.IndexOf(Environment.GetCommandLineArgs(),"-latteDemo")>=0)SeedLattePractice();}
  void Failure(string text,string stack,LogType type){if(type==LogType.Exception){File.WriteAllText(Path.Combine(review,"failure.txt"),text+"\n"+stack);Application.Quit(2);}}
  bool HitToolAt(Transform tool,Vector3 world){RaycastHit hit;return Physics.Raycast(art.Camera.ViewportPointToRay(art.Camera.WorldToViewportPoint(world)),out hit,20)&&hit.transform.IsChildOf(tool);}
  void Check(bool ok,string text){if(!ok)throw new Exception("FRONT_GRIND: "+text);}
  IEnumerator Settle(){float limit=Time.realtimeSinceStartup+3;while(Moving&&Time.realtimeSinceStartup<limit)yield return null;Check(!Moving,"motion finished");}
  IEnumerator Shot(string name){yield return new WaitForEndOfFrame();art.Camera.Render();var prior=RenderTexture.active;RenderTexture.active=art.Pixels;var image=new Texture2D(480,270,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,480,270),0,0);image.Apply();File.WriteAllBytes(Path.Combine(review,name+".png"),image.EncodeToPNG());Destroy(image);RenderTexture.active=prior;}
  IEnumerator Smoke(){yield return HandCameraSmoke();yield return null;Switch();Check(!Model.Running,"no basket switch gate");yield return Shot("frame_000");Check(Grab(),"grab handle");yield return Settle();yield return Shot("frame_001");Check(handCursor.Pose==HandPose.Grip&&handCursor.Visible,"single hand closes on pickup");var handAnchor=art.Camera.WorldToViewportPoint(BasketGrip());Check(Vector2.Distance(handCursor.Anchor,new Vector2(handAnchor.x,handAnchor.y))<.003f,"cursor attached to actual handle");Reach(new Vector3(art.Dock.x,.72f,art.Dock.z));Drop();for(int i=0;i<5;i++){yield return new WaitForSeconds(.1f);yield return Shot("frame_"+(i+2).ToString("D3"));}yield return Settle();Check(Model.Slot==CraftSlot.Grinder&&Vector3.Distance(art.Tool.position,art.Dock)<.001f,"seat actual cradle");Switch();yield return new WaitForSeconds(.4f);Check(Model.Running&&Model.Grounds>0,"grains land");Check(!Grab()&&!Model.Running,"pickup stops motor before withdrawal");yield return new WaitForSeconds(.35f);Check(Model.Flying==0,"last grains land");Switch();int n=7;float limit=Time.realtimeSinceStartup+10;while(!Model.Ready&&Time.realtimeSinceStartup<limit){yield return new WaitForSeconds(.16f);Check(Mathf.Abs(Model.Beans+Model.Grounds+Model.Flying+Model.Waste-60)<.01f,"mass conservation");yield return Shot("frame_"+(n++).ToString("D3"));}Check(Model.Ready,"18 grams complete");Check(Grab(),"withdraw grip");yield return Settle();Reach(new Vector3(art.Dock.x,.72f,-.45f));yield return Shot("frame_"+(n++).ToString("D3"));Reach(new Vector3(art.Mat.x,.72f,art.Mat.z));Drop();for(int i=0;i<6;i++){yield return new WaitForSeconds(.1f);yield return Shot("frame_"+(n++).ToString("D3"));}yield return Settle();Check(Model.Complete&&Vector3.Distance(art.Tool.position,art.Mat)<.001f,"full basket returns intact");Check(HitToolAt(art.Distributor,art.Distributor.position+new Vector3(.21f,.09f,0)),"wide leveler pickup hit");Check(PickPrep(1),"pick leveler");yield return Settle();ReachPrep(art.Mat+new Vector3(.45f,0,-.45f));DropPrep();yield return Settle();Check(prepContact,"forgiving leveler placement");
   for(int i=0;i<12;i++){RotatePrep(25);yield return Shot("frame_"+(n++).ToString("D3"));Check(handCursor.Pose==HandPose.Grip,"cursor grips leveling tool");}EndRotate();yield return Settle();Check(Prep.Leveled,"level surface");
   Check(HitToolAt(art.Tamper,art.Tamper.position+new Vector3(.17f,.12f,0)),"wide tamper pickup hit");Check(PickPrep(2),"pick tamper");yield return Settle();ReachPrep(art.Mat+new Vector3(-.45f,0,-.45f));DropPrep();yield return Settle();Check(prepContact,"forgiving tamper placement");Check(Prep.BeginTamp(),"press begins on leveled basket");
   for(int i=0;i<12;i++){PressPrep(i/11f,.05f);yield return Shot("frame_"+(n++).ToString("D3"));Check(handCursor.Pose==HandPose.Press,"cursor presses tamper");}for(int i=0;i<6;i++){PressPrep(1,.05f);yield return null;}EndPress();yield return Settle();Check(Prep.Complete,"press then lift complete");Check(motion==null,"camera-only pause setup");cameraMotion=art.Camera.transform.DOMoveX(art.Camera.transform.position.x,.2f);brewTurning=true;TogglePause();Check(paused&&!cameraMotion.IsPlaying()&&!brewTurning,"pause stops camera and cancels handle drag");TogglePause();yield return Settle();yield return Shot("frame_"+(n++).ToString("D3"));
   Check(Grab(),"grab again");yield return Settle();Reach(new Vector3(1.7f,.72f,.2f));Drop();yield return Settle();Check(Model.Complete,"invalid drop restores filled basket");Check(Grab(),"lift tamped basket for machine");yield return Settle();pointerOffset=Vector3.zero;var approach=art.Camera.WorldToViewportPoint(art.GroupSeat+new Vector3(.38f,-.1f,-.59f));DragHeld(new Vector2(approach.x,approach.y));Check(NearMachine(),"visual approach within broad dock area");yield return Shot("dock_00-assisted-approach");Drop();yield return Settle();Check(Vector3.Distance(art.Tool.position,art.GroupSeat)<.001f,"assisted insertion meets group head");Check(Brew.Inserted&&!Brew.Locked,"insert before locking");yield return Shot("brew_00-inserted");SwitchBrew();Check(!Brew.Running,"unlocked pump blocked");
   for(int i=0;i<8;i++){TurnBrew(5);yield return Shot("brew_01-turn-"+i);}Check(Brew.Locked,"handle locked");SwitchBrew();Check(!Brew.Running,"no cup pump blocked");Check(HitToolAt(art.Cup,art.Cup.position+new Vector3(.27f,.13f,0)),"cup handle can be grabbed");Check(GrabCup(),"pick cup");yield return Settle();ReachCup(art.CupHome);DropCup();yield return Settle();Check(!Brew.CupDocked,"rack drop does not count as cup seat");SwitchBrew();Check(!Brew.Running,"rack cup cannot start extraction");Check(GrabCup(),"pick cup for assisted placement");yield return Settle();ReachCup(art.CupSeat+new Vector3(.45f,0,-.5f));yield return Shot("cup_00-assisted-approach");DropCup();yield return Settle();Check(Brew.CupDocked&&Vector3.Distance(art.Cup.position,art.CupSeat)<.001f,"offset cup snaps exactly under spouts");yield return Shot("brew_02-cup");SwitchBrew();Check(Brew.Running,"pump begins");limit=Time.realtimeSinceStartup+15;int brewFrame=0;
   while(!Brew.Complete&&Time.realtimeSinceStartup<limit){yield return new WaitForSeconds(.22f);Check(Mathf.Abs(Brew.Pumped-Brew.InFlight-Brew.InCup-Brew.Spilled)<.01f,"espresso conservation");yield return Shot("brew_03-flow-"+(brewFrame++).ToString("D3"));}Check(Brew.Complete,"36 grams in cup");Check(!Grab(),"locked basket cannot be lifted");yield return Shot("brew_04-finished");yield return LatteSmoke();ResetStation();yield return new WaitForSeconds(.4f);Check(!Moving&&!held&&Model.Grounds==0&&art.Tool.position==art.Mat&&!Brew.Inserted&&Brew.InCup==0&&!cupHeld,"reset cancels pose");File.WriteAllText(Path.Combine(review,"result.json"),"{\"passed\":true,\"render\":\"actual 480x270 play camera\",\"scope\":\"scripted controller inputs; not OS mouse\",\"steps\":\"lift, seat, switch, grains, withdraw, set down, level, tamp, insert, turn lock, cup, espresso, easy latte\"}");Debug.Log("FRONT_GRIND_SMOKE_PASSED");Application.Quit(0);}
  void OnDestroy(){supportHand?.Dispose();handCursor?.Dispose();Kill();if(cameraMotion!=null&&cameraMotion.IsActive())cameraMotion.Kill();if(art!=null){art.Pixels.Release();Destroy(art.Pixels);}if(font)Destroy(font);}
 }
